// ============================================================================
// NODE: "Parse JSONL"   (Code node, Run Once for All Items)
// Input: items with binary files (Form upload, or "Read Files from Disk").
// Output: one item per article row. Rows are passed through unchanged.
// ============================================================================
const out = [];
