const FEED_BY_PUB = { 'Invezz': 'invezz_en', 'Invezz - German': 'invezz_de', 'Invezz - Dutch': 'invezz_nl', 'ActionForex': 'actionforex', 'International Business Times UK': 'ibtimes_uk', 'Zacks Investment Research': 'zacks' };

const seen = new Set();
const articles = [];
